from collections import Counter


def getDistinctPairs(investmentReturns, goal):
    cnt = Counter(investmentReturns)
    pairs = 0
    for x, c in cnt.items():
        y = goal - x
        if x < y:
            pairs += c * cnt.get(y, 0)
        elif x == y:
            pairs += c * (c - 1) // 2
    return pairs

import java.util.*;
class Solution {
    public long getDistinctPairs(int[] investmentReturns, long goal) {
        Map<Long, Long> cnt = new HashMap<>();
        for (int x : investmentReturns) cnt.merge((long) x, 1L, Long::sum);
        long pairs = 0;
        Set<Long> seen = new HashSet<>();
        for (Map.Entry<Long, Long> e : cnt.entrySet()) {
            long x = e.getKey(), c = e.getValue();
            if (seen.contains(x)) continue;
            long comp = goal - x;
            if (comp == x) pairs += c * (c - 1) / 2;
            else if (cnt.containsKey(comp)) {
                pairs += c * cnt.get(comp);
                seen.add(comp);
            }
            seen.add(x);
        }
        return pairs;
    }
}

class Solution {
public:
    long long getDistinctPairs(vector<int>& investmentReturns, long long goal) {
        unordered_map<long long, long long> cnt;
        for (int x : investmentReturns) cnt[x]++;
        long long pairs = 0;
        unordered_set<long long> seen;
        for (auto& [x, c] : cnt) {
            if (seen.count(x)) continue;
            long long comp = goal - x;
            if (comp == x) pairs += c * (c - 1) / 2;
            else if (cnt.count(comp)) {
                pairs += c * cnt[comp];
                seen.insert(comp);
            }
            seen.insert(x);
        }
        return pairs;
    }
};
